entries.target:
$d = Get-MpThreatDetection | Sort-Object InitialDetectionTime -Descending
if (-not $d) { 'Aucune menace détectée dans l''historique.' } else {
  $t = @{}; Get-MpThreat | ForEach-Object { $t[$_.ThreatID] = $_.ThreatName }
  $d | Select-Object InitialDetectionTime,@{n='Menace';e={$t[$_.ThreatID]}},ActionSuccess,@{n='Fichiers';e={$_.Resources -join ' | '}} | Format-List }

$r = Get-ComputerRestorePoint
if (-not $r) { 'Aucun point de restauration (protection du système désactivée ?)' } else {
$r | Select-Object SequenceNumber,@{n='Date';e={$_.ConvertToDateTime($_.CreationTime)}},Description | Format-Table -AutoSize }

Get-ChildItem -LiteralPath "{DOSSIER}" -Directory -Force -ErrorAction SilentlyContinue | ForEach-Object {
  $s = (Get-ChildItem -LiteralPath $_.FullName -Recurse -File -Force -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum
  [pscustomobject]@{ 'Taille (Mo)' = [math]::Round($s / 1MB, 1); Dossier = $_.Name }
} | Sort-Object 'Taille (Mo)' -Descending | Format-Table -AutoSize

$names = netsh wlan show profiles | Select-String '(?:Profil Tous les utilisateurs|All User Profile)\s*:\s*(.+)$' | ForEach-Object { $_.Matches[0].Groups[1].Value.Trim() }
if (-not $names) { 'Aucun profil Wi-Fi enregistré sur ce PC.' }
foreach ($n in $names) { $k = netsh wlan show profile name="$n" key=clear | Select-String '(?:Contenu de la cl.|Key Content)\s*:\s*(.+)$' | ForEach-Object { $_.Matches[0].Groups[1].Value.Trim() }
  [pscustomobject]@{ Reseau = $n; Cle = $k } }
